std::string AveroxCrypto::generateKey() {
    std::vector<unsigned char> key(config_.keySize);

    if (RAND_bytes(key.data(), static_cast<int>(key.size())) != 1) {
        throw std::runtime_error("Key generation failed");
    }

    ${features.telemetry ? 'std::cout << "[AVEROX] Key generated successfully" << std::endl;' : ''}

