std::string AveroxCrypto::encrypt(const std::string& data, const std::string& key) {
    try {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            throw std::runtime_error("Failed to create cipher context");
        }

        // Convert hex key to bytes
        std::vector<unsigned char> keyBytes;
        for (size_t i = 0; i < key.length(); i += 2) {
            std::string byteString = key.substr(i, 2);
            keyBytes.push_back(static_cast<unsigned char>(std::stoi(byteString, nullptr, 16)));
        }

        // Generate IV
        std::vector<unsigned char> iv(config_.ivSize);
        if (RAND_bytes(iv.data(), static_cast<int>(iv.size())) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("IV generation failed");
        }

        // Initialize encryption
        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, keyBytes.data(), iv.data()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Encryption initialization failed");
