        std::vector<unsigned char> result;
        result.insert(result.end(), iv.begin(), iv.end());
        result.insert(result.end(), ciphertext.begin(), ciphertext.begin() + ciphertext_len);
        result.insert(result.end(), tag.begin(), tag.end());

        ${features.telemetry ? 'std::cout << "[AVEROX] Data encrypted successfully" << std::endl;' : ''}

        // Convert to hex string
        std::ostringstream oss;
        for (auto byte : result) {
            oss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(byte);
        }
        return oss.str();

    } catch (const std::exception& e) {
        ${features.selfHealing ? 'return handleEncryptionError(e, data, key);' : 'throw std::runtime_error("Encryption failed: " + std::string(e.what()));'}
    }
}

std::string AveroxCrypto::decrypt(const std::string& encryptedData, const std::string& key) {
    try {
        // Convert hex strings to bytes
        std::vector<unsigned char> keyBytes;
        for (size_t i = 0; i < key.length(); i += 2) {
            std::string byteString = key.substr(i, 2);
            keyBytes.push_back(static_cast<unsigned char>(std::stoi(byteString, nullptr, 16)));
        }

        std::vector<unsigned char> data;
        for (size_t i = 0; i < encryptedData.length(); i += 2) {
            std::string byteString = encryptedData.substr(i, 2);
            data.push_back(static_cast<unsigned char>(std::stoi(byteString, nullptr, 16)));
        }

        // Extract IV, ciphertext, and tag
        std::vector<unsigned char> iv(data.begin(), data.begin() + config_.ivSize);
        std::vector<unsigned char> tag(data.end() - config_.tagSize, data.end());
        std::vector<unsigned char> ciphertext(data.begin() + config_.ivSize, data.end() - config_.tagSize);

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            throw std::runtime_error("Failed to create cipher context");
        }

        // Initialize decryption
        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, keyBytes.data(), iv.data()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Decryption initialization failed");
        }

        // Decrypt
        std::vector<unsigned char> plaintext(ciphertext.size());
        int len;
        int plaintext_len;

        if (EVP_DecryptUpdate(ctx, plaintext.data(), &len, ciphertext.data(), static_cast<int>(ciphertext.size())) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Decryption failed");
        }
        plaintext_len = len;

        // Set authentication tag
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, config_.tagSize, tag.data()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to set authentication tag");
        }

        // Finalize decryption
        if (EVP_DecryptFinal_ex(ctx, plaintext.data() + len, &len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Decryption verification failed");
        }
        plaintext_len += len;

        EVP_CIPHER_CTX_free(ctx);

        ${features.telemetry ? 'std::cout << "[AVEROX] Data decrypted successfully" << std::endl;' : ''}

        return std::string(reinterpret_cast<const char*>(plaintext.data()), plaintext_len);

    } catch (const std::exception& e) {
        ${features.selfHealing ? 'return handleDecryptionError(e, encryptedData, key);' : 'throw std::runtime_error("Decryption failed: " + std::string(e.what()));'}
    }
}

${features.selfHealing ? `
std::string AveroxCrypto::handleEncryptionError(const std::exception& e, const std::string& data, const std::string& key) {
    std::cerr << "[AVEROX-HEALING] Encryption failed, attempting recovery: " << e.what() << std::endl;
    try {
        return encrypt(data, key); // Retry once
    } catch (const std::exception& healingError) {
        throw std::runtime_error("Encryption failed even after healing: " + std::string(healingError.what()));
    }
}

std::string AveroxCrypto::handleDecryptionError(const std::exception& e, const std::string& encryptedData, const std::string& key) {
    std::cerr << "[AVEROX-HEALING] Decryption failed: " << e.what() << std::endl;
    throw std::runtime_error("Decryption failed: " + std::string(e.what()));
}
` : ''}

