 * ${sdk.name} SDK for React Native
 * Version: ${sdk.version}
 * Generated by Averox Crypto System
 */

import { NativeModules, Platform } from 'react-native';
import CryptoJS from 'crypto-js';

const { AveroxCryptoNative } = NativeModules;

class AveroxCrypto {
  constructor(config = {}) {
    this.config = {
      keySize: config.keySize || 256,
      algorithm: config.algorithm || 'AES-GCM',
      ...config
    };

    ${features.telemetry ? `
    this.telemetryEnabled = true;
    console.log('[AVEROX] React Native SDK initialized');
    ` : ''}
  }

  async generateKey() {
    try {
      if (Platform.OS === 'ios' || Platform.OS === 'android') {
        // Use native implementation for better performance
        return await AveroxCryptoNative.generateKey();
      } else {
        // Fallback to JavaScript implementation
        const key = CryptoJS.lib.WordArray.random(this.config.keySize / 8);

        ${features.telemetry ? 'console.log("[AVEROX] Key generated (JS fallback)");' : ''}

        return CryptoJS.enc.Base64.stringify(key);
      }
    } catch (error) {
      throw new Error(\`Key generation failed: \${error.message}\`);
    }
  }

  async encrypt(data, key) {
    try {
      if (Platform.OS === 'ios' || Platform.OS === 'android') {
        // Use native implementation
        const result = await AveroxCryptoNative.encrypt(data, key);

        ${features.telemetry ? 'console.log("[AVEROX] Data encrypted (native)");' : ''}

        return result;
      } else {
        // JavaScript fallback
        const keyWordArray = CryptoJS.enc.Base64.parse(key);
        const iv = CryptoJS.lib.WordArray.random(16);

        const encrypted = CryptoJS.AES.encrypt(data, keyWordArray, {
          iv: iv,
          mode: CryptoJS.mode.GCM,
          padding: CryptoJS.pad.NoPadding
        });

        const result = {
          encrypted: encrypted.ciphertext.toString(),
          iv: iv.toString(),
          algorithm: 'AES-GCM'
        };

        ${features.telemetry ? 'console.log("[AVEROX] Data encrypted (JS fallback)");' : ''}

        return CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(JSON.stringify(result)));
      }
    } catch (error) {
      ${features.selfHealing ? `
      console.warn('[AVEROX-HEALING] Encryption failed, attempting recovery...');
      return this.handleEncryptionError(error, data, key);
      ` : `
      throw new Error(\`Encryption failed: \${error.message}\`);
      `}
    }
  }

  async decrypt(encryptedData, key) {
    try {
      if (Platform.OS === 'ios' || Platform.OS === 'android') {
        // Use native implementation
        const result = await AveroxCryptoNative.decrypt(encryptedData, key);

        ${features.telemetry ? 'console.log("[AVEROX] Data decrypted (native)");' : ''}

        return result;
      } else {
        // JavaScript fallback
        const keyWordArray = CryptoJS.enc.Base64.parse(key);
        const dataStr = CryptoJS.enc.Utf8.stringify(CryptoJS.enc.Base64.parse(encryptedData));
        const data = JSON.parse(dataStr);

        const decrypted = CryptoJS.AES.decrypt({
          ciphertext: CryptoJS.enc.Hex.parse(data.encrypted)
        }, keyWordArray, {
          iv: CryptoJS.enc.Hex.parse(data.iv),
          mode: CryptoJS.mode.GCM,
          padding: CryptoJS.pad.NoPadding
        });

        ${features.telemetry ? 'console.log("[AVEROX] Data decrypted (JS fallback)");' : ''}

        return decrypted.toString(CryptoJS.enc.Utf8);
      }
    } catch (error) {
      ${features.selfHealing ? `
      console.warn('[AVEROX-HEALING] Decryption failed...');
      return this.handleDecryptionError(error, encryptedData, key);
      ` : `
      throw new Error(\`Decryption failed: \${error.message}\`);
      `}
    }
  }

  ${features.selfHealing ? `
  async handleEncryptionError(error, data, key) {
    try {
      // Attempt recovery with different algorithm
      return await this.encrypt(data, key);
    } catch (healingError) {
      throw new Error(\`Encryption failed even after healing: \${healingError.message}\`);
    }
  }

  async handleDecryptionError(error, encryptedData, key) {
    throw new Error(\`Decryption failed: \${error.message}\`);
  }
  ` : ''}
}

