  recordApiUsage(usage: InsertApiUsage): Promise<ApiUsage>;

  // Dashboard statistics
  getDashboardStats(tenantId: string): Promise<{
    activeSDKs: number;
    encryptedRequests: number;
    keyRotations: number;
