export class DatabaseStorage implements IStorage {
  // User operations (required for Authentication)
  async getUser(id: string): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.id, id));
    return user;
  }

  async upsertUser(userData: UpsertUser): Promise<User> {
    const [user] = await db
      .insert(users)
      .values(userData)
      .onConflictDoUpdate({
        target: users.id,
        set: {
          ...userData,
          updatedAt: new Date(),
        },
      })
      .returning();
    return user;
  }

  async updateUser(id: string, updates: Partial<User>): Promise<User> {
    const [user] = await db
      .update(users)
      .set({
        ...updates,
        updatedAt: new Date(),
      })
      .where(eq(users.id, id))
      .returning();
    return user;
  }

  async getUserByEmail(email: string): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.email, email));
    return user;
  }

  // Email verification operations
  async setVerificationToken(userId: string, tokenHash: string, expires: Date): Promise<void> {
    await db
      .update(users)
      .set({
        emailVerificationTokenHash: tokenHash,
        emailVerificationExpires: expires,
        updatedAt: new Date(),
      })
      .where(eq(users.id, userId));
  }

  async findByVerificationToken(tokenHash: string): Promise<User | undefined> {
    const [user] = await db
      .select()
      .from(users)
      .where(eq(users.emailVerificationTokenHash, tokenHash));

    // Check if token is expired
    if (user && user.emailVerificationExpires && user.emailVerificationExpires < new Date()) {
      return undefined; // Token expired
    }

    return user;
  }

  async verifyUser(userId: string): Promise<void> {
    await db
      .update(users)
      .set({
        isEmailVerified: true,
        emailVerificationTokenHash: null,
        emailVerificationExpires: null,
        updatedAt: new Date(),
      })
      .where(eq(users.id, userId));
  }

  async clearVerificationToken(userId: string): Promise<void> {
    await db
      .update(users)
      .set({
        emailVerificationTokenHash: null,
        emailVerificationExpires: null,
        updatedAt: new Date(),
      })
      .where(eq(users.id, userId));
  }

  // Password reset operations
  async setPasswordResetToken(email: string, tokenHash: string, expires: Date): Promise<User | undefined> {
    const [user] = await db
      .update(users)
      .set({
        passwordResetTokenHash: tokenHash,
        passwordResetExpires: expires,
        updatedAt: new Date(),
      })
      .where(eq(users.email, email))
      .returning();
    return user;
  }

  async findByPasswordResetToken(tokenHash: string): Promise<User | undefined> {
    const [user] = await db
      .select()
      .from(users)
      .where(eq(users.passwordResetTokenHash, tokenHash));

    // Check if token is expired
    if (user && user.passwordResetExpires && user.passwordResetExpires < new Date()) {
      return undefined; // Token expired
    }

    return user;
  }

  async clearPasswordResetToken(userId: string): Promise<void> {
    await db
      .update(users)
      .set({
        passwordResetTokenHash: null,
        passwordResetExpires: null,
        updatedAt: new Date(),
      })
      .where(eq(users.id, userId));
  }

  async updateUserPassword(userId: string, newPasswordHash: string): Promise<void> {
    await db
      .update(users)
      .set({
        passwordHash: newPasswordHash,
        updatedAt: new Date(),
      })
      .where(eq(users.id, userId));
  }

  // Trial and subscription operations
  async createTrialUser(userData: {
    email: string;
    firstName: string;
    lastName: string;
    companyName: string;
    website?: string;
    phoneNumber: string;
    passwordHash: string;
  }): Promise<User> {
    // Set trial period (14 days from now)
    const trialStartDate = new Date();
    const trialEndDate = new Date();
    trialEndDate.setDate(trialEndDate.getDate() + 14);

    const [user] = await db
      .insert(users)
      .values({
        email: userData.email,
        firstName: userData.firstName,
        lastName: userData.lastName, 
        companyName: userData.companyName,
        website: userData.website,
        phoneNumber: userData.phoneNumber,
        passwordHash: userData.passwordHash,
        subscriptionStatus: 'trialing',
        subscriptionPlan: 'starter',
        trialStartDate,
        trialEndDate,
        role: 'developer',
        isEmailVerified: false, // Will be verified through email
      })
      .returning();
    return user;
  }

  // ====== NOTIFICATION OPERATIONS ======
  async getNotifications(tenantId: string, userId?: string, limit: number = 50): Promise<Notification[]> {
    const query = db
      .select()
      .from(notifications)
      .where(
        userId 
          ? and(eq(notifications.tenantId, tenantId), eq(notifications.userId, userId))
          : and(eq(notifications.tenantId, tenantId), isNull(notifications.userId))
      )
      .orderBy(desc(notifications.createdAt))
      .limit(limit);

    return await query;
  }

  async getUnreadNotificationCount(tenantId: string, userId?: string): Promise<number> {
    const result = await db
      .select({ count: count() })
      .from(notifications)
      .where(
        and(
          eq(notifications.tenantId, tenantId),
          eq(notifications.isRead, false),
          userId 
            ? eq(notifications.userId, userId)
            : isNull(notifications.userId)
        )
      );

    return result[0]?.count || 0;
  }

  async createNotification(notification: InsertNotification): Promise<Notification> {
    const [newNotification] = await db
      .insert(notifications)
      .values(notification)
      .returning();
    return newNotification;
  }

  async markNotificationAsRead(notificationId: string): Promise<Notification> {
    const [notification] = await db
      .update(notifications)
      .set({ 
        isRead: true, 
        readAt: new Date() 
      })
      .where(eq(notifications.id, notificationId))
      .returning();
    return notification;
  }

  async markAllNotificationsAsRead(tenantId: string, userId?: string): Promise<void> {
