      await db
        .update(sdkDeployments)
        .set({
          totalOperations: newTotal,
          successRate: newSuccessRate,
          lastHeartbeat: new Date(),
          updatedAt: new Date()
        })
        .where(eq(sdkDeployments.id, current.id));
    }
