  async updateComplianceReporting(id: string, lastReportGenerated: Date, nextReportDue?: Date): Promise<void> {
    const updateData: any = {
      lastReportGenerated,
      updatedAt: new Date()
    };

    if (nextReportDue) {
      updateData.nextReportDue = nextReportDue;
    }

    await db
      .update(compliancePolicies)
