  --chart-1: hsl(0, 0%, 100%);
  --chart-2: hsl(0, 0%, 75%);
  --chart-3: hsl(0, 0%, 50%);
  --chart-4: hsl(0, 0%, 25%);
  --chart-5: hsl(0, 0%, 65%);
  --sidebar: hsl(0, 0%, 0%);
  --sidebar-foreground: hsl(0, 0%, 100%);
  --sidebar-primary: hsl(0, 0%, 100%);
  --sidebar-primary-foreground: hsl(0, 0%, 0%);
  --sidebar-accent: hsl(0, 0%, 15%);
  --sidebar-accent-foreground: hsl(0, 0%, 100%);
