                  Risk Assessment
                </CardTitle>
              </CardHeader>
              <CardContent>
                {readinessLoading ? (
                  <div className="space-y-3">
                    <div className="h-4 bg-muted rounded animate-pulse"></div>
                    <div className="h-4 bg-muted rounded animate-pulse"></div>
                    <div className="h-4 bg-muted rounded animate-pulse"></div>
