          memoryUsageMB: this.platformProfile.memoryGB * 1024 * 0.8 // 80% of RAM
        },
        algorithmSwitching: {
          enabled: true,
          switchThreshold: 0.2, // 20% performance difference
          cooldownPeriod: 600 // 10 minutes
        },
