    EncryptedData *result = [[EncryptedData alloc] init];
    result.iv = [iv base64EncodedStringWithOptions:0];
    result.ciphertext = [ciphertext base64EncodedStringWithOptions:0];
    result.tag = [tag base64EncodedStringWithOptions:0];

    return result;
