    if (!isCompliant) {
      console.log('\n⚠️  CRITICAL: SDK does not meet external audit requirements');
      console.log('   Action required: Fix failing checks before production use');
    }

    return {
      results,
      compliance: complianceRate,
      passed: passedChecks,
      total: totalChecks,
