import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Loader, TestTube, CheckCircle, AlertCircle } from "lucide-react";
import { Database, Lock, Shield as CloudShield } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormDescription, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Checkbox } from "@/components/ui/checkbox";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";

const baseConfigSchema = z.object({
  name: z.string().min(1, "Provider name is required"),
  provider: z.enum(["aws_kms", "azure_key_vault", "gcp_kms"]),
  region: z.string().min(1, "Region is required"),
  description: z.string().optional(),
});

const awsConfigSchema = baseConfigSchema.extend({
  provider: z.literal("aws_kms"),
  accessKeyId: z.string().min(1, "Access Key ID is required"),
  secretAccessKey: z.string().min(1, "Secret Access Key is required"),
  roleArn: z.string().optional(),
});

const azureConfigSchema = baseConfigSchema.extend({
  provider: z.literal("azure_key_vault"),
  vaultUrl: z.string().url("Valid vault URL is required"),
  tenantId: z.string().min(1, "Tenant ID is required"),
  clientId: z.string().min(1, "Client ID is required"),
  clientSecret: z.string().min(1, "Client Secret is required"),
  useManagedIdentity: z.boolean().default(false),
});

const gcpConfigSchema = baseConfigSchema.extend({
  provider: z.literal("gcp_kms"),
  projectId: z.string().min(1, "Project ID is required"),
  keyRingId: z.string().min(1, "Key Ring ID is required"),
  location: z.string().min(1, "Location is required"),
  serviceAccountKey: z.string().optional(),
  useWorkloadIdentity: z.boolean().default(false),
});

type ProviderConfig = z.infer<typeof awsConfigSchema> | z.infer<typeof azureConfigSchema> | z.infer<typeof gcpConfigSchema>;

interface ProviderConfigFormProps {
  onSuccess: () => void;
}

export default function ProviderConfigForm({ onSuccess }: ProviderConfigFormProps) {
  const [selectedProvider, setSelectedProvider] = useState<"aws_kms" | "azure_key_vault" | "gcp_kms">("aws_kms");
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null);
  const { toast } = useToast();

  const form = useForm<ProviderConfig>({
    resolver: zodResolver(
      selectedProvider === "aws_kms" ? awsConfigSchema :
      selectedProvider === "azure_key_vault" ? azureConfigSchema :
      gcpConfigSchema
    ),
    defaultValues: {
      name: "",
      provider: selectedProvider,
      region: "",
      description: "",
    } as ProviderConfig,
  });

  // Test connection mutation
  const testConnectionMutation = useMutation({
    mutationFn: async (config: Partial<ProviderConfig>) => {
      const response = await apiRequest("POST", "/api/cloud-providers/test", config);
      return response.json();
    },
    onSuccess: (data) => {
      setTestResult({ success: true, message: "Connection successful!" });
    },
    onError: (error: Error) => {
      setTestResult({ success: false, message: error.message });
    },
  });

  // Create provider mutation
  const createProviderMutation = useMutation({
    mutationFn: async (config: ProviderConfig) => {
      const response = await apiRequest("POST", "/api/cloud-providers", config);
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Provider Created",
        description: "Cloud provider has been configured successfully.",
      });
      onSuccess();
    },
    onError: (error: Error) => {
      toast({
        title: "Configuration Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: ProviderConfig) => {
    createProviderMutation.mutate(data);
  };

  const handleTestConnection = () => {
    const values = form.getValues();
    testConnectionMutation.mutate(values);
  };

  const handleProviderChange = (provider: "aws_kms" | "azure_key_vault" | "gcp_kms") => {
    setSelectedProvider(provider);
    setTestResult(null);
    form.reset({
      name: "",
      provider,
      region: "",
      description: "",
    } as ProviderConfig);
  };

  return (
    <div className="space-y-6">
      {/* Provider Selection */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {[
          { id: "aws_kms", name: "AWS KMS", icon: Database, description: "Amazon Key Management Service" },
          { id: "azure_key_vault", name: "Azure Key Vault", icon: Lock, description: "Microsoft Azure Key Vault" },
          { id: "gcp_kms", name: "Google Cloud KMS", icon: CloudShield, description: "Google Cloud Key Management" },
        ].map((provider) => (
          <Card 
            key={provider.id}
            className={`cursor-pointer transition-all ${
              selectedProvider === provider.id 
                ? "ring-2 ring-primary border-primary" 
                : "hover:shadow-md"
            }`}
            onClick={() => handleProviderChange(provider.id as any)}
            data-testid={`provider-${provider.id}`}
          >
            <CardContent className="flex flex-col items-center text-center p-6">
              <div className="text-3xl mb-2 text-muted-foreground">
                {(() => {
                  const IconComponent = provider.icon;
                  return <IconComponent className="w-12 h-12" aria-label={provider.name} />;
                })()}
              </div>
              <h3 className="font-semibold">{provider.name}</h3>
              <p className="text-sm text-muted-foreground">{provider.description}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Configuration Form */}
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
          {/* Basic Configuration */}
          <Card>
            <CardHeader>
              <CardTitle>Basic Configuration</CardTitle>
              <CardDescription>
                General settings for your {selectedProvider.replace('_', ' ').toUpperCase()} provider.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <FormField
                control={form.control}
                name="name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Provider Name</FormLabel>
                    <FormControl>
                      <Input placeholder="e.g., Production AWS KMS" {...field} data-testid="input-name" />
                    </FormControl>
                    <FormDescription>
                      A friendly name to identify this provider configuration.
                    </FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="region"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Region</FormLabel>
                    <FormControl>
                      <Input 
                        placeholder={
                          selectedProvider === "aws_kms" ? "us-east-1" :
                          selectedProvider === "azure_key_vault" ? "eastus" :
                          "us-central1"
                        } 
                        {...field} 
                        data-testid="input-region"
                      />
                    </FormControl>
                    <FormDescription>
                      The primary region for this provider configuration.
                    </FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="description"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Description (Optional)</FormLabel>
                    <FormControl>
                      <Textarea 
                        placeholder="Additional details about this provider configuration..."
                        {...field} 
                        data-testid="input-description"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </CardContent>
          </Card>

          {/* Provider-Specific Configuration */}
          <Card>
            <CardHeader>
              <CardTitle>Authentication Configuration</CardTitle>
              <CardDescription>
                Security credentials and authentication settings for {selectedProvider.replace('_', ' ').toUpperCase()}.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {selectedProvider === "aws_kms" && (
                <>
                  <FormField
                    control={form.control}
                    name="accessKeyId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Access Key ID</FormLabel>
                        <FormControl>
                          <Input placeholder="AKIA..." {...field} data-testid="input-access-key" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="secretAccessKey"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Secret Access Key</FormLabel>
                        <FormControl>
                          <Input type="password" {...field} data-testid="input-secret-key" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="roleArn"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Role ARN (Optional)</FormLabel>
                        <FormControl>
                          <Input placeholder="arn:aws:iam::123456789012:role/KMSRole" {...field} data-testid="input-role-arn" />
                        </FormControl>
                        <FormDescription>
                          For cross-account access or enhanced security.
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </>
              )}

              {selectedProvider === "azure_key_vault" && (
                <>
                  <FormField
                    control={form.control}
                    name="vaultUrl"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Key Vault URL</FormLabel>
                        <FormControl>
                          <Input placeholder="https://your-vault.vault.azure.net/" {...field} data-testid="input-vault-url" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="tenantId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Tenant ID</FormLabel>
                        <FormControl>
                          <Input {...field} data-testid="input-tenant-id" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="clientId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Client ID</FormLabel>
                        <FormControl>
                          <Input {...field} data-testid="input-client-id" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="clientSecret"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Client Secret</FormLabel>
                        <FormControl>
                          <Input type="password" {...field} data-testid="input-client-secret" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="useManagedIdentity"
                    render={({ field }) => (
                      <FormItem className="flex flex-row items-start space-x-3 space-y-0">
                        <FormControl>
                          <Checkbox
                            checked={field.value}
                            onCheckedChange={field.onChange}
                            data-testid="checkbox-managed-identity"
                          />
                        </FormControl>
                        <div className="space-y-1 leading-none">
                          <FormLabel>Use Managed Identity</FormLabel>
                          <FormDescription>
                            Use Azure Managed Identity for authentication (recommended for Azure workloads).
                          </FormDescription>
                        </div>
                      </FormItem>
                    )}
                  />
                </>
              )}

              {selectedProvider === "gcp_kms" && (
                <>
                  <FormField
                    control={form.control}
                    name="projectId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Project ID</FormLabel>
                        <FormControl>
                          <Input placeholder="my-gcp-project" {...field} data-testid="input-project-id" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="keyRingId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Key Ring ID</FormLabel>
                        <FormControl>
                          <Input placeholder="my-key-ring" {...field} data-testid="input-key-ring" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="location"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Location</FormLabel>
                        <FormControl>
                          <Input placeholder="global" {...field} data-testid="input-location" />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="serviceAccountKey"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Service Account Key (JSON)</FormLabel>
                        <FormControl>
                          <Textarea 
                            placeholder="Paste your service account key JSON here..."
                            className="font-mono text-sm"
                            rows={4}
                            {...field} 
                            data-testid="input-service-account"
                          />
                        </FormControl>
                        <FormDescription>
                          Leave empty to use default application credentials.
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="useWorkloadIdentity"
                    render={({ field }) => (
                      <FormItem className="flex flex-row items-start space-x-3 space-y-0">
                        <FormControl>
                          <Checkbox
                            checked={field.value}
                            onCheckedChange={field.onChange}
                            data-testid="checkbox-workload-identity"
                          />
                        </FormControl>
                        <div className="space-y-1 leading-none">
                          <FormLabel>Use Workload Identity</FormLabel>
                          <FormDescription>
                            Use GKE Workload Identity for authentication (recommended for GKE workloads).
                          </FormDescription>
                        </div>
                      </FormItem>
                    )}
                  />
                </>
              )}
            </CardContent>
          </Card>

          {/* Test Connection */}
          <Card>
            <CardHeader>
              <CardTitle>Connection Test</CardTitle>
              <CardDescription>
                Test the connection to ensure your configuration is correct before saving.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center space-x-4">
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleTestConnection}
                  disabled={testConnectionMutation.isPending}
                  data-testid="button-test-connection"
                >
                  {testConnectionMutation.isPending ? (
                    <Loader className="w-4 h-4 mr-2 animate-spin" />
                  ) : (
                    <TestTube className="w-4 h-4 mr-2" />
                  )}
                  Test Connection
                </Button>

                {testResult && (
                  <div className={`flex items-center space-x-2 ${
                    testResult.success ? 'text-green-600' : 'text-red-600'
                  }`}>
                    {testResult.success ? (
                      <CheckCircle className="w-4 h-4" />
                    ) : (
                      <AlertCircle className="w-4 h-4" />
                    )}
                    <span className="text-sm">{testResult.message}</span>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Submit */}
          <div className="flex items-center justify-end space-x-4">
            <Button
              type="submit"
              disabled={createProviderMutation.isPending}
              data-testid="button-save-provider"
            >
              {createProviderMutation.isPending ? (
                <Loader className="w-4 h-4 mr-2 animate-spin" />
              ) : null}
              Save Provider Configuration
            </Button>
          </div>
        </form>
      </Form>
    </div>
  );
}

client/src/pages/cloud-providers.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Plus, Cloud, Shield, AlertCircle, CheckCircle, Settings, Eye, Trash2, MoreHorizontal } from "lucide-react";
import { Database, Lock, Shield as CloudShield } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";

// Provider configuration component
import ProviderConfigForm from "@/components/ProviderConfigForm";

interface CloudProvider {
  id: string;
  name: string;
  provider: "aws_kms" | "azure_key_vault" | "gcp_kms";
  region: string;
  status: "connected" | "disconnected" | "error";
  lastHealthCheck: string;
  keysManaged: number;
  createdAt: string;
  description?: string;
}

const providerIcons = {
  aws_kms: Database,
  azure_key_vault: Lock, 
  gcp_kms: CloudShield
};

const providerNames = {
  aws_kms: "AWS KMS",
  azure_key_vault: "Azure Key Vault",
  gcp_kms: "Google Cloud KMS"
};

export default function CloudProviders() {
  const [isConfigDialogOpen, setIsConfigDialogOpen] = useState(false);
  const [selectedProvider, setSelectedProvider] = useState<CloudProvider | null>(null);
  const [activeTab, setActiveTab] = useState("overview");
  const { toast } = useToast();

  // Fetch cloud providers
  const { data: providers = [], isLoading, error } = useQuery<CloudProvider[]>({
    queryKey: ["/api/cloud-providers"],
  });

  // Delete provider mutation
  const deleteProviderMutation = useMutation({
    mutationFn: async (providerId: string) => {
      const response = await apiRequest("DELETE", `/api/cloud-providers/${providerId}`);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/cloud-providers"] });
      toast({
        title: "Provider Deleted",
        description: "Cloud provider configuration has been removed successfully.",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Delete Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Test connection mutation
  const testConnectionMutation = useMutation({
    mutationFn: async (providerId: string) => {
      const response = await apiRequest("POST", `/api/cloud-providers/${providerId}/test`);
      return response.json();
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["/api/cloud-providers"] });
      toast({
        title: "Connection Test",
        description: data.success ? "Connection successful!" : "Connection failed",
        variant: data.success ? "default" : "destructive",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Test Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case "connected": return "text-green-600 bg-green-50 border-green-200";
      case "disconnected": return "text-yellow-600 bg-yellow-50 border-yellow-200";
      case "error": return "text-red-600 bg-red-50 border-red-200";
      default: return "text-gray-600 bg-gray-50 border-gray-200";
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "connected": return <CheckCircle className="w-4 h-4" />;
      case "disconnected": return <AlertCircle className="w-4 h-4" />;
      case "error": return <AlertCircle className="w-4 h-4" />;
      default: return <AlertCircle className="w-4 h-4" />;
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="text-muted-foreground">Loading cloud providers...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="text-red-600">Failed to load cloud providers</div>
      </div>
    );
  }

  return (
    <div className="space-y-6" data-testid="page-cloud-providers">
      {/* Header Actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <div className="flex items-center space-x-2">
            <Cloud className="w-6 h-6 text-blue-600" />
            <span className="text-lg font-semibold">Multi-Cloud KMS</span>
          </div>
          <Badge variant="outline" className="text-blue-600 border-blue-200">
            {providers.length} Provider{providers.length !== 1 ? 's' : ''} Configured
          </Badge>
        </div>

        <Dialog open={isConfigDialogOpen} onOpenChange={setIsConfigDialogOpen}>
          <DialogTrigger asChild>
            <Button data-testid="button-add-provider">
              <Plus className="w-4 h-4 mr-2" />
              Add Provider
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-4xl max-h-[80vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Configure Cloud Provider</DialogTitle>
              <DialogDescription>
                Add a new cloud KMS provider to manage encryption keys across multiple clouds.
              </DialogDescription>
            </DialogHeader>
            <ProviderConfigForm 
              onSuccess={() => {
                setIsConfigDialogOpen(false);
                queryClient.invalidateQueries({ queryKey: ["/api/cloud-providers"] });
              }} 
            />
          </DialogContent>
        </Dialog>
      </div>

      {/* Main Content */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="overview" data-testid="tab-overview">Overview</TabsTrigger>
          <TabsTrigger value="health" data-testid="tab-health">Health Status</TabsTrigger>
          <TabsTrigger value="configuration" data-testid="tab-configuration">Configuration</TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-6">
          {providers.length === 0 ? (
            <Card>
              <CardContent className="flex flex-col items-center justify-center py-12">
                <Cloud className="w-12 h-12 text-muted-foreground mb-4" />
                <h3 className="text-lg font-semibold mb-2">No Cloud Providers Configured</h3>
                <p className="text-muted-foreground text-center mb-4">
                  Get started by adding your first cloud KMS provider to enable multi-cloud key management.
                </p>
                <Button onClick={() => setIsConfigDialogOpen(true)} data-testid="button-get-started">
                  <Plus className="w-4 h-4 mr-2" />
                  Add Your First Provider
                </Button>
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {providers.map((provider) => (
                <Card key={provider.id} className="hover:shadow-md transition-shadow" data-testid={`card-provider-${provider.id}`}>
                  <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-3">
                        <div className="text-2xl text-muted-foreground">
                          {(() => {
                            const IconComponent = providerIcons[provider.provider];
                            return <IconComponent className="w-8 h-8" aria-label={providerNames[provider.provider]} />;
                          })()}
                        </div>
                        <div>
                          <CardTitle className="text-lg">{provider.name}</CardTitle>
                          <CardDescription>{providerNames[provider.provider]}</CardDescription>
                        </div>
                      </div>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="sm" data-testid={`menu-provider-${provider.id}`}>
                            <MoreHorizontal className="w-4 h-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => testConnectionMutation.mutate(provider.id)}>
                            <Eye className="w-4 h-4 mr-2" />
                            Test Connection
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => setSelectedProvider(provider)}>
                            <Settings className="w-4 h-4 mr-2" />
                            Configure
                          </DropdownMenuItem>
                          <DropdownMenuItem 
                            onClick={() => deleteProviderMutation.mutate(provider.id)}
                            className="text-red-600"
                          >
                            <Trash2 className="w-4 h-4 mr-2" />
                            Delete
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-muted-foreground">Status</span>
                      <Badge className={getStatusColor(provider.status)}>
                        {getStatusIcon(provider.status)}
                        <span className="ml-1 capitalize">{provider.status}</span>
                      </Badge>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-muted-foreground">Region</span>
                      <span className="text-sm font-medium">{provider.region}</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-muted-foreground">Keys Managed</span>
                      <span className="text-sm font-medium">{provider.keysManaged}</span>
                    </div>
                    <div className="text-xs text-muted-foreground">
                      Last check: {new Date(provider.lastHealthCheck).toLocaleString()}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="health" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center space-x-2">
                <Shield className="w-5 h-5" />
                <span>Provider Health Status</span>
              </CardTitle>
              <CardDescription>
                Monitor the health and connectivity of all configured cloud providers.
              </CardDescription>
            </CardHeader>
            <CardContent>
              {providers.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  No providers configured to monitor.
                </div>
              ) : (
                <div className="space-y-4">
                  {providers.map((provider) => (
                    <div 
                      key={provider.id} 
                      className="flex items-center justify-between p-4 border rounded-lg"
                      data-testid={`health-${provider.id}`}
                    >
                      <div className="flex items-center space-x-4">
                        <div className="text-xl text-muted-foreground">
                          {(() => {
                            const IconComponent = providerIcons[provider.provider];
                            return <IconComponent className="w-6 h-6" aria-label={providerNames[provider.provider]} />;
                          })()}
                        </div>
                        <div>
                          <div className="font-medium">{provider.name}</div>
                          <div className="text-sm text-muted-foreground">
                            {providerNames[provider.provider]} • {provider.region}
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center space-x-4">
                        <Badge className={getStatusColor(provider.status)}>
                          {getStatusIcon(provider.status)}
                          <span className="ml-1 capitalize">{provider.status}</span>
                        </Badge>
                        <Button 
                          variant="outline" 
                          size="sm"
                          onClick={() => testConnectionMutation.mutate(provider.id)}
                          disabled={testConnectionMutation.isPending}
                          data-testid={`test-${provider.id}`}
                        >
                          Test Connection
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="configuration" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Provider Configuration</CardTitle>
              <CardDescription>
                Manage authentication, regions, and security settings for your cloud providers.
              </CardDescription>
            </CardHeader>
            <CardContent>
              {providers.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  No providers configured.
                </div>
              ) : (
                <div className="space-y-6">
                  {providers.map((provider) => (
                    <div 
                      key={provider.id} 
                      className="border rounded-lg p-6"
                      data-testid={`config-${provider.id}`}
                    >
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center space-x-3">
                          <div className="text-xl text-muted-foreground">
                          {(() => {
                            const IconComponent = providerIcons[provider.provider];
                            return <IconComponent className="w-6 h-6" aria-label={providerNames[provider.provider]} />;
                          })()}
                        </div>
                          <div>
                            <h3 className="font-semibold">{provider.name}</h3>
                            <p className="text-sm text-muted-foreground">
                              {providerNames[provider.provider]}
                            </p>
                          </div>
                        </div>
                        <Button variant="outline" size="sm">
                          <Settings className="w-4 h-4 mr-2" />
                          Edit Configuration
                        </Button>
                      </div>
                      <div className="grid grid-cols-2 gap-4 text-sm">
                        <div>
                          <span className="text-muted-foreground">Region:</span>
                          <span className="ml-2 font-medium">{provider.region}</span>
                        </div>
                        <div>
                          <span className="text-muted-foreground">Created:</span>
                          <span className="ml-2 font-medium">
                            {new Date(provider.createdAt).toLocaleDateString()}
                          </span>
                        </div>
                        {provider.description && (
                          <div className="col-span-2">
                            <span className="text-muted-foreground">Description:</span>
                            <span className="ml-2">{provider.description}</span>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

client/src/pages/key-distribution.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { GitBranch, RefreshCw, CheckCircle, AlertTriangle, Loader, Eye, Settings, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Form, FormControl, FormDescription, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";

interface KeyDistribution {
  id: string;
  keyId: string;
  providerConfigId: string;
  providerKeyId: string;
  distributionStatus: "synced" | "pending" | "failed" | "out_of_sync";
  lastSyncAt: string;
  syncError?: string;
  metadata: {
    keyName: string;
    providerName: string;
    providerType: string;
    region: string;
  };
}

interface KeyReplication {
  id: string;
  sourceKeyId: string;
  targetProviderConfigId: string;
  targetKeyId: string;
  replicationStatus: "active" | "failed" | "pending";
  lastReplicationAt: string;
  replicationError?: string;
  metadata: {
    sourceProvider: string;
    targetProvider: string;
    sourceRegion: string;
    targetRegion: string;
  };
}

const statusColors = {
  synced: "text-green-600 bg-green-50 border-green-200",
  pending: "text-yellow-600 bg-yellow-50 border-yellow-200", 
  failed: "text-red-600 bg-red-50 border-red-200",
  out_of_sync: "text-orange-600 bg-orange-50 border-orange-200",
  active: "text-green-600 bg-green-50 border-green-200"
};

const statusIcons = {
  synced: <CheckCircle className="w-4 h-4" />,
  pending: <Loader className="w-4 h-4 animate-spin" />,
  failed: <AlertTriangle className="w-4 h-4" />,
  out_of_sync: <AlertTriangle className="w-4 h-4" />,
  active: <CheckCircle className="w-4 h-4" />
};

// Form schema for creating key distributions
const distributionFormSchema = z.object({
  keyId: z.string().min(1, "Please select a key"),
  providerConfigId: z.string().min(1, "Please select a provider"),
  distributionType: z.enum(["immediate", "scheduled", "manual"]),
  scheduleAt: z.string().optional(),
  autoSync: z.boolean().default(true),
  syncInterval: z.string().default("24h"),
  notes: z.string().optional(),
});

type DistributionFormData = z.infer<typeof distributionFormSchema>;

export default function KeyDistribution() {
  const [activeTab, setActiveTab] = useState("distributions");
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const { toast } = useToast();

  // Form for creating distributions
  const form = useForm<DistributionFormData>({
    resolver: zodResolver(distributionFormSchema),
    defaultValues: {
      distributionType: "immediate",
      autoSync: true,
      syncInterval: "24h",
    },
  });

  // Fetch key distributions
  const { data: distributions = [], isLoading: distributionsLoading } = useQuery<KeyDistribution[]>({
    queryKey: ["/api/key-distributions"],
  });

  // Fetch key replications
  const { data: replications = [], isLoading: replicationsLoading } = useQuery<KeyReplication[]>({
    queryKey: ["/api/key-replications"],
  });

  // Fetch available keys for distribution
  const { data: availableKeys = [] } = useQuery<any[]>({
    queryKey: ["/api/keys"],
  });

  // Fetch cloud providers
  const { data: cloudProviders = [] } = useQuery<any[]>({
    queryKey: ["/api/cloud-providers"],
  });

  // Create distribution mutation
  const createDistributionMutation = useMutation({
    mutationFn: async (data: DistributionFormData) => {
      const response = await apiRequest("POST", "/api/key-distributions", data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/key-distributions"] });
      setIsCreateDialogOpen(false);
      form.reset();
      toast({
        title: "Distribution Created",
        description: "Key distribution has been configured successfully.",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Creation Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Sync mutation
  const syncMutation = useMutation({
    mutationFn: async (distributionId: string) => {
      const response = await apiRequest("POST", `/api/key-distributions/${distributionId}/sync`);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/key-distributions"] });
      toast({
        title: "Sync Initiated",
        description: "Key synchronization has been started.",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Sync Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Sync all mutation
  const syncAllMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest("POST", "/api/key-distributions/sync-all");

      // Check if response is JSON before parsing
      const contentType = response.headers.get("content-type");
      if (contentType && contentType.includes("application/json")) {
        return await response.json();
      } else {
        // If not JSON, just return success indicator
        return { success: true, message: "Sync completed" };
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/key-distributions"] });
      queryClient.invalidateQueries({ queryKey: ["/api/key-replications"] });
      toast({
        title: "Global Sync Initiated",
        description: "All key distributions are being synchronized.",
      });
    },
    onError: (error: any) => {
      console.error("Sync error:", error);
      toast({
        title: "Global Sync Failed", 
        description: error?.message || "Failed to sync all distributions. Please try again.",
        variant: "destructive",
      });
    },
  });

  const isLoading = distributionsLoading || replicationsLoading;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="text-muted-foreground">Loading key distributions...</div>
      </div>
    );
  }

  return (
    <div className="space-y-6" data-testid="page-key-distribution">
      {/* Header Actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <div className="flex items-center space-x-2">
            <GitBranch className="w-6 h-6 text-blue-600" />
            <span className="text-lg font-semibold">Multi-Cloud Key Distribution</span>
          </div>
          <Badge variant="outline" className="text-blue-600 border-blue-200">
            {distributions.length} Distribution{distributions.length !== 1 ? 's' : ''}
          </Badge>
        </div>

        <div className="flex items-center space-x-2">
          <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
            <DialogTrigger asChild>
              <Button variant="outline" data-testid="button-create-distribution">
                <Plus className="w-4 h-4 mr-2" />
                Create Distribution
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-2xl">
              <DialogHeader>
                <DialogTitle>Create Key Distribution</DialogTitle>
                <DialogDescription>
                  Configure how and where to distribute your encryption keys across cloud providers.
                </DialogDescription>
              </DialogHeader>

              <Form {...form}>
                <form onSubmit={form.handleSubmit((data) => createDistributionMutation.mutate(data))} className="space-y-6">
                  <div className="grid grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="keyId"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Select Key</FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
                            <FormControl>
                              <SelectTrigger data-testid="select-key">
                                <SelectValue placeholder="Choose a key to distribute" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              {availableKeys.map((key: any) => (
                                <SelectItem key={key.id} value={key.id}>
                                  {key.name || key.id}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <FormDescription>
                            Select the encryption key you want to distribute
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="providerConfigId"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Target Provider</FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
                            <FormControl>
                              <SelectTrigger data-testid="select-provider">
                                <SelectValue placeholder="Choose destination provider" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              {cloudProviders.map((provider: any) => (
                                <SelectItem key={provider.id} value={provider.id}>
                                  {provider.name} ({provider.providerType})
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <FormDescription>
                            Target cloud provider for key distribution
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>

                  <FormField
                    control={form.control}
                    name="distributionType"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Distribution Type</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger data-testid="select-distribution-type">
                              <SelectValue />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            <SelectItem value="immediate">Immediate Distribution</SelectItem>
                            <SelectItem value="scheduled">Scheduled Distribution</SelectItem>
                            <SelectItem value="manual">Manual Distribution</SelectItem>
                          </SelectContent>
                        </Select>
                        <FormDescription>
                          When should this key be distributed
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  {form.watch("distributionType") === "scheduled" && (
                    <FormField
                      control={form.control}
                      name="scheduleAt"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Schedule Date & Time</FormLabel>
                          <FormControl>
                            <Input 
                              type="datetime-local" 
                              {...field} 
                              data-testid="input-schedule-at"
                            />
                          </FormControl>
                          <FormDescription>
                            When to execute the distribution
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  )}

                  <div className="grid grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="autoSync"
                      render={({ field }) => (
                        <FormItem className="flex flex-row items-center justify-between rounded-lg border p-4">
                          <div className="space-y-0.5">
                            <FormLabel className="text-base">Auto Sync</FormLabel>
                            <FormDescription>
                              Automatically sync changes with the provider
                            </FormDescription>
                          </div>
                          <FormControl>
                            <input
                              type="checkbox"
                              checked={field.value}
                              onChange={field.onChange}
                              data-testid="checkbox-auto-sync"
                              className="rounded"
                            />
                          </FormControl>
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="syncInterval"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Sync Interval</FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
                            <FormControl>
                              <SelectTrigger data-testid="select-sync-interval">
                                <SelectValue />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              <SelectItem value="1h">Every Hour</SelectItem>
                              <SelectItem value="6h">Every 6 Hours</SelectItem>
                              <SelectItem value="24h">Daily</SelectItem>
                              <SelectItem value="168h">Weekly</SelectItem>
                            </SelectContent>
                          </Select>
                          <FormDescription>
                            How often to sync with the provider
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>

                  <FormField
                    control={form.control}
                    name="notes"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Notes (Optional)</FormLabel>
                        <FormControl>
                          <Textarea 
                            placeholder="Add any notes about this distribution..."
                            {...field}
                            data-testid="textarea-notes"
                          />
                        </FormControl>
                        <FormDescription>
                          Additional context or requirements for this distribution
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <div className="flex items-center justify-end space-x-2">
                    <Button 
                      type="button" 
                      variant="outline" 
                      onClick={() => setIsCreateDialogOpen(false)}
                      data-testid="button-cancel"
                    >
                      Cancel
                    </Button>
                    <Button 
                      type="submit" 
                      disabled={createDistributionMutation.isPending}
                      data-testid="button-create"
                    >
                      {createDistributionMutation.isPending && (
                        <Loader className="w-4 h-4 mr-2 animate-spin" />
                      )}
                      Create Distribution
                    </Button>
                  </div>
                </form>
              </Form>
            </DialogContent>
          </Dialog>

          <Button 
            onClick={() => syncAllMutation.mutate()}
            disabled={syncAllMutation.isPending}
            data-testid="button-sync-all"
          >
            <RefreshCw className={`w-4 h-4 mr-2 ${syncAllMutation.isPending ? 'animate-spin' : ''}`} />
            Sync All
          </Button>
        </div>
      </div>

      {/* Main Content */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="distributions" data-testid="tab-distributions">Key Distributions</TabsTrigger>
          <TabsTrigger value="replications" data-testid="tab-replications">Cross-Region Replications</TabsTrigger>
          <TabsTrigger value="analytics" data-testid="tab-analytics">Sync Analytics</TabsTrigger>
        </TabsList>

        <TabsContent value="distributions" className="space-y-6">
          {distributions.length === 0 ? (
            <Card>
              <CardContent className="flex flex-col items-center justify-center py-12">
                <GitBranch className="w-12 h-12 text-muted-foreground mb-4" />
                <h3 className="text-lg font-semibold mb-2">No Key Distributions Found</h3>
                <p className="text-muted-foreground text-center mb-4">
                  Key distributions will appear here once you configure cloud providers and distribute keys across them.
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-4">
              {distributions.map((distribution) => (
                <Card key={distribution.id} data-testid={`distribution-${distribution.id}`}>
                  <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                      <div>
                        <CardTitle className="text-lg">{distribution.metadata.keyName}</CardTitle>
                        <CardDescription>
                          Distributed to {distribution.metadata.providerName} ({distribution.metadata.region})
                        </CardDescription>
                      </div>
                      <div className="flex items-center space-x-2">
                        <Badge className={statusColors[distribution.distributionStatus]}>
                          {statusIcons[distribution.distributionStatus]}
                          <span className="ml-1 capitalize">{distribution.distributionStatus.replace('_', ' ')}</span>
                        </Badge>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => syncMutation.mutate(distribution.id)}
                          disabled={syncMutation.isPending}
                          data-testid={`sync-${distribution.id}`}
                        >
                          <RefreshCw className={`w-4 h-4 ${syncMutation.isPending ? 'animate-spin' : ''}`} />
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                      <div>
                        <span className="text-muted-foreground block">Key ID</span>
                        <span className="font-mono text-xs">{distribution.keyId}</span>
                      </div>
                      <div>
                        <span className="text-muted-foreground block">Provider Key ID</span>
                        <span className="font-mono text-xs">{distribution.providerKeyId}</span>
                      </div>
                      <div>
                        <span className="text-muted-foreground block">Provider Type</span>
                        <span className="capitalize">{distribution.metadata.providerType.replace('_', ' ')}</span>
                      </div>
                      <div>
                        <span className="text-muted-foreground block">Last Sync</span>
                        <span>{new Date(distribution.lastSyncAt).toLocaleString()}</span>
                      </div>
                    </div>

                    {distribution.syncError && (
                      <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
                        <div className="flex items-center space-x-2 text-red-600 text-sm">
                          <AlertTriangle className="w-4 h-4" />
                          <span className="font-medium">Sync Error:</span>
                        </div>
                        <p className="text-red-700 text-sm mt-1">{distribution.syncError}</p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="replications" className="space-y-6">
          {replications.length === 0 ? (
            <Card>
              <CardContent className="flex flex-col items-center justify-center py-12">
                <GitBranch className="w-12 h-12 text-muted-foreground mb-4" />
                <h3 className="text-lg font-semibold mb-2">No Cross-Region Replications</h3>
                <p className="text-muted-foreground text-center mb-4">
                  Cross-region key replications will appear here when configured for high availability.
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-4">
              {replications.map((replication) => (
                <Card key={replication.id} data-testid={`replication-${replication.id}`}>
                  <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                      <div>
                        <CardTitle className="text-lg">
                          {replication.metadata.sourceProvider} → {replication.metadata.targetProvider}
                        </CardTitle>
                        <CardDescription>
                          {replication.metadata.sourceRegion} to {replication.metadata.targetRegion}
                        </CardDescription>
                      </div>
                      <Badge className={statusColors[replication.replicationStatus]}>
                        {statusIcons[replication.replicationStatus]}
                        <span className="ml-1 capitalize">{replication.replicationStatus}</span>
                      </Badge>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 text-sm">
                      <div>
                        <span className="text-muted-foreground block">Source Key</span>
                        <span className="font-mono text-xs">{replication.sourceKeyId}</span>
                      </div>
                      <div>
                        <span className="text-muted-foreground block">Target Key</span>
                        <span className="font-mono text-xs">{replication.targetKeyId}</span>
                      </div>
                      <div>
                        <span className="text-muted-foreground block">Last Replication</span>
                        <span>{new Date(replication.lastReplicationAt).toLocaleString()}</span>
                      </div>
                    </div>

                    {replication.replicationError && (
                      <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
                        <div className="flex items-center space-x-2 text-red-600 text-sm">
                          <AlertTriangle className="w-4 h-4" />
                          <span className="font-medium">Replication Error:</span>
                        </div>
                        <p className="text-red-700 text-sm mt-1">{replication.replicationError}</p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="analytics" className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-lg">Distribution Status</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {Object.entries(
                    distributions.reduce((acc, dist) => {
                      acc[dist.distributionStatus] = (acc[dist.distributionStatus] || 0) + 1;
                      return acc;
                    }, {} as Record<string, number>)
                  ).map(([status, count]) => (
                    <div key={status} className="flex items-center justify-between">
                      <div className="flex items-center space-x-2">
                        {statusIcons[status as keyof typeof statusIcons]}
                        <span className="capitalize text-sm">{status.replace('_', ' ')}</span>
                      </div>
                      <span className="font-medium">{count}</span>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-lg">Provider Distribution</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {Object.entries(
                    distributions.reduce((acc, dist) => {
                      acc[dist.metadata.providerType] = (acc[dist.metadata.providerType] || 0) + 1;
                      return acc;
                    }, {} as Record<string, number>)
                  ).map(([provider, count]) => (
                    <div key={provider} className="flex items-center justify-between">
                      <span className="capitalize text-sm">{provider.replace('_', ' ')}</span>
                      <span className="font-medium">{count}</span>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-lg">Replication Health</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {Object.entries(
                    replications.reduce((acc, rep) => {
                      acc[rep.replicationStatus] = (acc[rep.replicationStatus] || 0) + 1;
                      return acc;
                    }, {} as Record<string, number>)
                  ).map(([status, count]) => (
                    <div key={status} className="flex items-center justify-between">
                      <div className="flex items-center space-x-2">
                        {statusIcons[status as keyof typeof statusIcons]}
                        <span className="capitalize text-sm">{status}</span>
                      </div>
                      <span className="font-medium">{count}</span>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

